def has_close_elements(numbers, threshold):
    for i in range(len(numbers) - 1):
        for j in range(i + 1, len(numbers)):
            if abs(numbers[i] - numbers[j]) <= threshold:
                return True
    return False

def truncate_number(number: float) -> float:
    """
    Decomposes a positive floating point number into its integer part and decimals, and returns the decimals.

    :param number: A positive floating point number to be decomposed.
    :return: The decimals of the number.
    """
    if number < 0:
        raise ValueError("Number must be positive.")
    return number - number.floor()

def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def find_number_combinations():
    numbers = []

    # Iterate over the first number
    for i in range(1, 10):
        # Iterate over the second number, ensuring it is twice the first number
        for j in range(2 * i, 10):
            # Iterate over the third number, ensuring it is three times the first number
            for k in range(3 * i, 10):
                # Check if the third number is greater than the other two
                if k > j:
                    break
                # Check if the combination is valid
                if i * 8 + j * 3 + k * 1 == 1000:
                    numbers.append((i, j, k))

    # Sort the valid combinations based on the first number
    numbers.sort(key=lambda x: x[0])

    return numbers

def cantor_numbering(N):
    def g(i, j):
        if i == j:
            return 1
        else:
            return g(i - 1, j - 1) + g(i - 1, j)

    n = int(N ** 0.5)
    k = int(n * (n + 1) / 2)
    if k > N:
        return str(N) + "/" + str(N + 1)
    else:
        i = int((n * (n + 1)) / 2)
        j = int(((n - k + 1) * (n - k + 2)) / 2)
        return str(g(i, j)) + "/" + str(g(n, n + 1))

