def string_transformation(A, B, rules):
    q = collections.deque([(A, 0)])
    visited = set()
    while q:
        node, step = q.popleft()
        if node == B:
            return step
        if step > 10:
            continue
        for rule in rules:
            src, target = rule
            if node.startswith(src):
                new_node = node.replace(src, target, 1)
                if new_node not in visited:
                    q.append((new_node, step + 1))
                    visited.add(new_node)
